#!/usr/bin/env python3
"""Write standards/REVIEW_REGISTER.md: every standards entry that still needs review (status < approved, or specialist review).

    python3 standards/review_register.py
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from standards.accessor import Standards, STATUS_ORDER

S = Standards()
rows = S.review_register()
cnt = {s: sum(1 for e in S.entries.values() if e["status"] == s) for s in STATUS_ORDER}
L = ["# Standards review register", "",
     "Generated by `python3 standards/review_register.py` from `standards/data/`. **Do not edit by hand.**", "",
     "- **What this is:** values the software currently uses for AS 5100 / AS 1170 rules.",
     "- **None is verified.** Every calculation that uses them is flagged **UNVERIFIED** until the entry is `approved` by the responsible engineer, checked against an authorised copy (ADR-009).",
     "- **Edition and amendment** are not recorded in the code. They are left blank and must be set at review.", "",
     "| Status | Entries |", "|---|---|"] + [f"| {s} | {n} |" for s, n in cnt.items()] + [
     "", f"**{len(rows)} entries need review; {sum(r['specialist'] for r in rows)} are flagged for specialist interpretation.**", "",
     "| Id | Standard | Clause (as coded) | Status | Specialist | Code location | Note |", "|---|---|---|---|---|---|---|"]
for r in rows:
    L.append(f"| `{r['id']}` | {r['standard']} | {r['clause'] or '—'} | {r['status']} | {'yes' if r['specialist'] else ''} | `{r['used_by']}` | {r['note'].replace('|', '/')} |")
L += ["", "## How an entry is reviewed", "",
      "1. Check the value against an authorised copy of the named Standard. Record the edition and amendment.",
      "2. Set `reference.authorised_source` (which copy), `review.reviewer`, `review.date` and `review.method`.",
      "3. Set the status to `checked` (independent check) or `approved` (responsible engineer).",
      "4. Agents may not set `checked` / `approved`; the loader rejects it.",
      "5. If the code value is wrong, fix the code (and re-run the baseline). Re-running `standards/extract_from_code.py` resets the status of any entry whose code value changed."]
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "REVIEW_REGISTER.md"), "w").write("\n".join(L) + "\n")
print(f"standards/REVIEW_REGISTER.md: {len(rows)} entries need review")
